def main() -> None:
    root = Path(__file__).resolve().parents[1] / "data"
    workbook = Workbook()
    metadata = workbook.active
    assert metadata is not None
    metadata.title = "README"
    metadata.append(["Учебный классификатор, созданный для тренажёра; не нормативный классификатор АРМ-112."])
    metadata.append(["Типы = осмысленные сочетания объекта и характера происшествия; исходник scripts/build_training_data.py."])
    services = workbook.create_sheet("services")
    services.append(["code", "name", "short_name", "is_visible", "sort_order"])
    primary = [("MCHS", "МЧС"), ("MVD", "МВД"), ("SMP", "Скорая медицинская помощь"), ("MOSGAZ", "Мосгаз"), ("MOSVODOKANAL", "Мосводоканал"), ("MOEK", "МОЭК"), ("ROSSETI", "Электросети"), ("LIFT", "Лифтовая диспетчерская"), ("ROADS", "Дорожная служба"), ("GREEN", "Зелёное хозяйство"), ("CLEAN", "Служба уборки"), ("LIGHT", "Наружное освещение"), ("TELECOM", "Служба связи"), ("ANIMALS", "Ветеринарная служба"), ("ECO", "Экологическая служба"), ("BUILD", "Строительный надзор"), ("DDS_CHERTANOVO", "ДДС Чертаново Южное"), ("INFORMATION", "Информационная служба")]
    districts = "Арбат;Басманный;Замоскворечье;Красносельский;Мещанский;Пресненский;Таганский;Тверской;Хамовники;Якиманка;Аэропорт;Беговой;Бескудниковский;Войковский;Головинский;Дмитровский;Коптево;Левобережный;Молжаниновский;Савёловский;Сокол;Тимирязевский;Ховрино;Хорошёвский;Алексеевский;Алтуфьевский;Бабушкинский;Бибирево;Бутырский;Лианозово;Лосиноостровский;Марфино;Марьина Роща;Останкинский;Отрадное;Ростокино;Свиблово;Северный;Ярославский;Даниловский".split(";")
    for i, (code, name) in enumerate(primary + [(f"DDS_{i:02}", f"ДДС {name}") for i, name in enumerate(districts)]):
        services.append([code, name, name, code != "INFORMATION", i])
    groups = workbook.create_sheet("incident_groups")
    groups.append(["code", "name", "sort_order"])
    types = workbook.create_sheet("incident_types")
    types.append(["code", "group_code", "name", "attributes", "difficulty", "services"])
    for i, (name, routing, problems, objects) in enumerate(GROUPS, 1):
        group_code = f"{i:02}"
        groups.append([group_code, name, i])
        for j, obj in enumerate(objects.split(";"), 1):
            for k, problem in enumerate(problems.split(";"), 1):
                attrs = {"level1": name, "level2": obj, "level3": problem}
                title = f"{name.lower()}: {obj}, {problem}"
                if (i, j, k) == (1, 1, 1):
                    title = "пожар: частный дом"
                    attrs = {"level1": "на улице", "level2": "частный дом", "level3": "открытое пламя"}
                types.append([f"{i:02}.{j:02}.{k:02}", group_code, title, json.dumps(attrs, ensure_ascii=False), min(10, 2 + k + (i in (1, 13, 21, 23))), routing])
    modifiers = workbook.create_sheet("modifier_services")
    modifiers.append(["modifier", "service_code"])
    for modifier, codes in {"THREAT_TO_PEOPLE": ["SMP"], "VICTIMS": ["SMP"], "FATALITIES": ["MVD", "SMP"], "NO_ACCESS": ["MCHS"], "ROAD_BLOCKED": ["MVD", "ROADS"], "CHILD_INVOLVED": ["SMP", "MVD"]}.items():
        for code in codes:
            modifiers.append([modifier, code])
    workbook.save(root / "classifier.xlsx")
    streets = "Дубнинская;Дубининская;Чертановская;Тверская;Арбат;Петровка;Сретенка;Мясницкая;Большая Дмитровка;Малая Дмитровка;Новослободская;Долгоруковская;Краснопролетарская;Бутырская;Тимирязевская;Смольная;Фестивальная;Лавочкина;Профсоюзная;Вавилова;Гарибальди;Обручева;Наметкина;Каховка;Азовская;Ялтинская;Сумская;Кировоградская;Дорожная;Подольских Курсантов;Газопровод;Академика Янгеля;Россошанская;Станционная;Садовая-Каретная;Лесная;Правды;Беговая;Планетная;Усиевича;Варшавское шоссе;Каширское шоссе;Ленинградское шоссе;Дмитровское шоссе;Ленинский проспект;Ленинградский проспект;Севастопольский проспект;Нахимовский проспект;Сиреневый бульвар;Чистопрудный бульвар".split(";")
    with (root / "streets.csv").open("w", encoding="utf-8", newline="") as out:
        writer = csv.writer(out)
        writer.writerow(["name", "district"])
        for name in streets:
            writer.writerow([name if any(w in name for w in ("шоссе", "проспект", "бульвар")) else name + " улица", "Москва"])
    print(f"Created {len(GROUPS)} groups, {len(GROUPS)*50} types, {len(primary)+len(districts)} services, {len(streets)} streets")


if __name__ == "__main__":
    main()
